package safetynet

// Manifest returns the orch-pinned marketplace manifest for a spec. Claude Code
// reads it from a local directory, so the pin is exactly what this file says:
// the plugin tree at one commit, not whatever upstream publishes next.
func Manifest(s Spec) ([]byte, error) {
	m := map[string]any{
		"name":  MarketplaceName,
		"owner": map[string]any{"name": "orch"},
		"metadata": map[string]any{
			"description": "Generated by orch; overwritten on every install. Pins third-party plugins to reviewed commits.",
		},
		"plugins": []any{
			map[string]any{
				"name":        PluginName,
				"description": "CC Safety Net v" + s.Version + ", pinned by orch to commit " + s.SHA + " (released " + s.ReleasedOn + ").",
				"source": map[string]any{
					"source": "url",
					"url":    s.RepoURL,
					"ref":    s.Ref,
					"sha":    s.SHA,
				},
				"category": "security",
			},
		},
	}
	return marshalJSON(m)
}
